<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';
import { Head, router, useForm } from '@inertiajs/vue3';
const props = defineProps<{ active_term:any; classes:any[]; selected_class_id:string; students:any[] }>();
const form = useForm({ records: props.students.map(s => ({ enrollment_id:s.enrollment_id, spiritual_predicate:s.spiritual_predicate, spiritual_description:s.spiritual_description, social_predicate:s.social_predicate, social_description:s.social_description })) });
const changeClass = (e:Event) => router.get('/penilaian/sikap', { class_group_id:(e.target as HTMLSelectElement).value }, { preserveState:false });
const submit = () => form.post('/penilaian/sikap', { preserveScroll:true });
const options = [{v:'excellent',l:'Sangat Baik'},{v:'good',l:'Baik'},{v:'fair',l:'Cukup'},{v:'needs_guidance',l:'Perlu Bimbingan'}];
</script>
<template><Head title="Penilaian Sikap"/><AppLayout><main class="view space-y-6"><section class="hero-card compact"><div><p class="eyebrow">Evaluasi · {{ active_term?.name ?? 'Belum ada semester aktif' }}</p><h1>Penilaian sikap siswa</h1><p>Rekam sikap spiritual dan sosial sebagai deskripsi yang akan disertakan dalam snapshot rapor.</p></div><select :value="selected_class_id" @change="changeClass"><option v-for="c in classes" :key="c.id" :value="c.id">{{ c.name }}</option></select></section><form @submit.prevent="submit"><section class="panel overflow-hidden"><div class="table-wrap"><table class="data-table"><thead><tr><th>Siswa</th><th>Sikap spiritual</th><th>Deskripsi spiritual</th><th>Sikap sosial</th><th>Deskripsi sosial</th></tr></thead><tbody><tr v-for="(s,i) in students" :key="s.enrollment_id"><td><strong>{{ s.name }}</strong><br><small>{{ s.nis }}</small></td><td><select v-model="form.records[i].spiritual_predicate"><option v-for="o in options" :key="o.v" :value="o.v">{{ o.l }}</option></select></td><td><textarea v-model="form.records[i].spiritual_description" required rows="2" placeholder="Contoh perilaku spiritual yang diamati"></textarea></td><td><select v-model="form.records[i].social_predicate"><option v-for="o in options" :key="o.v" :value="o.v">{{ o.l }}</option></select></td><td><textarea v-model="form.records[i].social_description" required rows="2" placeholder="Contoh perilaku sosial yang diamati"></textarea></td></tr><tr v-if="!students.length"><td colspan="5" class="empty-state">Tidak ada siswa aktif pada kelas ini.</td></tr></tbody></table></div></section><div class="form-actions"><p v-if="form.hasErrors" class="form-error">Lengkapi seluruh deskripsi sikap.</p><button class="primary-button" :disabled="form.processing || !students.length">Simpan penilaian sikap</button></div></form></main></AppLayout></template>
<style scoped>.compact{display:flex;align-items:center;justify-content:space-between;gap:1rem}.compact select,.data-table select,.data-table textarea{border:1px solid #cbd5e1;border-radius:.6rem;padding:.55rem;width:100%}.table-wrap{overflow:auto}.data-table textarea{min-width:230px}.data-table small{color:#64748b}.form-actions{display:flex;justify-content:flex-end;align-items:center;gap:1rem;margin-top:1rem}.form-error{color:#dc2626}.empty-state{text-align:center;padding:3rem;color:#64748b}@media(max-width:760px){.compact{align-items:stretch;flex-direction:column}}</style>
